-- public.team_schedule_range, household_schedule_range, get_event
begin;
create extension if not exists pgtap with schema extensions;
select * from no_plan();
create function pg_temp.n(q text) returns int language plpgsql as $f$ declare c int; begin execute q; get diagnostics c = row_count; return c; end $f$;

update public.profiles set display_name = 'Pat Ava' where id = 'a2222222-2222-2222-2222-222222222222';
-- Team A (club-linked, soccer): admin, coach, parents Ava/Ben, player Teen. Team B (basketball): coach B, parent Other.
-- Active on A: Ava, Ben, Teen. Inactive on A: Dan. Active on B: Cleo, Ivy (Ava's second team).

reset role;
reset role; set local role anon; select set_config('request.jwt.claims', '{"role":"anon"}', true);
select throws_ok($$ select * from public.team_schedule_range('a1000000-0000-0000-0000-00000000000a', '2027-06-01', '2027-07-01') $$, '42501', null, 'anonymous users cannot read ranges');
select throws_ok($$ select * from public.get_event('e1000000-0000-0000-0000-000000000001') $$, '42501', null, 'anonymous users cannot read an event');
reset role; select set_config('request.jwt.claims', '{"sub":"a2222222-2222-2222-2222-222222222222","role":"authenticated"}', true); set local role authenticated;
select is((select count(*)::int from public.team_schedule_range('a1000000-0000-0000-0000-00000000000a', '2027-06-01', '2027-07-01')), 1, 'only events inside the range');
select throws_ok($$ select * from public.team_schedule_range('a1000000-0000-0000-0000-00000000000a', '2027-07-01', '2027-06-01') $$, '23514', 'invalid_range', 'an inverted range is rejected');
select throws_ok($$ select * from public.team_schedule_range('a1000000-0000-0000-0000-00000000000a', '2027-01-01', '2028-01-01') $$, '23514', 'invalid_range', 'a range over 100 days is rejected');
select is((select string_agg(player_first_name || ':' || title || ':' || coalesce(rsvp_status, '-'), ',' order by starts_at, player_first_name) from public.household_schedule_range('2027-06-01', '2027-07-01')), 'Ava:In range:going,Teen:In range:-,Ivy:B game:-', 'household range: one row per child, per team');
select is((select title from public.get_event('e1000000-0000-0000-0000-000000000001')), 'In range', 'a rostered parent reads the event');
select is((select is_staff from public.get_event('e1000000-0000-0000-0000-000000000001')), false, 'and is not staff');
select is((select outcome || ':' || sport::text from public.get_event('e2000000-0000-0000-0000-00000000000b')), 'win:basketball', 'the result and sport come back with the event');
reset role; select set_config('request.jwt.claims', '{"sub":"a3333333-3333-3333-3333-333333333333","role":"authenticated"}', true); set local role authenticated;
select is_empty($$ select * from public.get_event('e2000000-0000-0000-0000-00000000000b') $$, 'a parent cannot read another team''s event');
select is_empty($$ select * from public.team_schedule_range('a2000000-0000-0000-0000-00000000000b', '2027-06-01', '2027-07-01') $$, 'nor another team''s range');
reset role; select set_config('request.jwt.claims', '{"sub":"a1111111-1111-1111-1111-111111111111","role":"authenticated"}', true); set local role authenticated;
select is((select is_staff from public.get_event('e1000000-0000-0000-0000-000000000001')), true, 'staff are flagged');
reset role; select set_config('request.jwt.claims', '{"sub":"a9999999-9999-9999-9999-999999999999","role":"authenticated"}', true); set local role authenticated;
select is_empty($$ select * from public.get_event('e1000000-0000-0000-0000-000000000001') $$, 'a stranger gets nothing');
select * from finish();
rollback;
